with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('ulighed', 'word', '8c539cd5-ebe0-55d4-9237-dc50c0a0afda', 1, 'noun', 'en', 'inequality', 'Der er stor ulighed i samfundet.', 'There is great inequality in society.'), ('hændelse', 'word', 'd7eaab93-5237-5f5a-9e10-0764eab02bd8', 1, 'noun', 'en', 'event, incident', 'Det var en mærkelig hændelse.', 'It was a strange incident.'), ('stabilitet', 'word', '172a128c-a083-5e4a-826f-1a70797cd50d', 1, 'noun', 'en', 'stability', 'Vi har brug for økonomisk stabilitet.', 'We need economic stability.'), ('kost', 'word', '2d7c4374-7a4d-54be-a694-9b7a42ddb322', 1, 'noun', 'en', 'diet', 'En sund kost er vigtig.', 'A healthy diet is important.'), ('kost', 'word', '8ee429a8-687d-517e-90af-decd0875009c', 2, 'noun', 'en', 'broom', 'Hun fejer gulvet med en kost.', 'She sweeps the floor with a broom.'), ('akademisk', 'word', '749da61c-e7db-5026-ab2b-b59bbe8b3b53', 1, 'adjective', null, 'academic', 'Han har en akademisk uddannelse.', 'He has an academic education.'), ('læserbrev', 'word', '56604d86-6a70-5927-93e8-3e702e6e1116', 1, 'noun', 'et', 'letter to the editor', 'Jeg har skrevet et læserbrev til avisen.', 'I have written a letter to the editor.'), ('moral', 'word', '0f6f6e23-c6ce-5717-9d95-f193d3b955b5', 1, 'noun', 'en', 'morals, moral character', 'Han har en høj moral.', 'He has high moral standards.'), ('moral', 'word', '95ebc14e-daa7-5e89-83ec-4877f91d5f04', 2, 'noun', 'en', 'moral (of a story)', 'Hvad er moralen i denne historie?', 'What is the moral of this story?'), ('blodig', 'word', '2df5d280-10fb-5b10-bb14-ff81bb78964c', 1, 'adjective', null, 'bloody', 'Han havde et blodigt sår på knæet.', 'He had a bloody wound on his knee.'), ('dirigent', 'word', '3ae42d36-6818-5461-a412-fcfe129e2438', 1, 'noun', 'en', 'conductor (orchestra)', 'Dirigenten løftede sin taktstok.', 'The conductor raised his baton.'), ('kendsgerning', 'word', '360ba981-10c0-5cc3-8675-41c5adf33d8a', 1, 'noun', 'en', 'fact', 'Det er en kendsgerning, at jorden er rund.', 'It is a fact that the earth is round.'), ('buks', 'word', '5d18f1b8-947b-5540-a3b1-7d9d3e8d499d', 1, 'noun', 'en', 'trousers, pants', 'Jeg har købt et par nye bukser.', 'I have bought a new pair of trousers.'), ('europæer', 'word', '1388b65d-c7bf-55e1-9b22-c1433d61fc00', 1, 'noun', 'en', 'European (person)', 'Han er europæer og bor i Danmark.', 'He is a European and lives in Denmark.'), ('fagbevægelse', 'word', '39217e1d-6341-53e2-861d-a69a0b8ab955', 1, 'noun', 'en', 'labor movement, trade union movement', 'Fagbevægelsen kæmper for bedre løn.', 'The labor movement fights for better pay.'), ('købmand', 'word', '5f199b5c-8c4f-5db8-9f61-b1cc153ea1c0', 1, 'noun', 'en', 'shopkeeper, grocer', 'Købmanden åbner sin butik tidligt.', 'The grocer opens his shop early.'), ('sårbar', 'word', '6e4c6068-7329-5fb8-a721-61f83ad296e3', 1, 'adjective', null, 'vulnerable', 'Børn er ofte mere sårbare end voksne.', 'Children are often more vulnerable than adults.'), ('spring', 'word', 'b03fe4b7-388d-53ea-92fc-4075eb4348af', 1, 'noun', 'et', 'jump, leap', 'Han tog et stort spring over vandet.', 'He took a big leap over the water.'), ('spring', 'word', '2aed4210-8e12-53bd-9568-7012237834f8', 2, 'noun', 'et', 'crack (in glass)', 'Der er et lille spring i glasset.', 'There is a small crack in the glass.'), ('sti', 'word', '5c0292ed-5cc2-50dd-bef4-bb4dd0a93892', 1, 'noun', 'en', 'path, trail', 'Vi går ad en lille sti gennem skoven.', 'We walk along a small path through the forest.'), ('slægt', 'word', 'a4b86e49-5443-543c-9fec-57ed5ad7fe04', 1, 'noun', 'en', 'family, lineage', 'Hun kommer fra en gammel slægt.', 'She comes from an old family line.'), ('slægt', 'word', 'b4b51979-f6c9-5ffd-baf6-23bbe402d7f6', 2, 'noun', 'en', 'kinship, relation', 'Der er slægt mellem de to familier.', 'There is kinship between the two families.'), ('bogstav', 'word', 'e1eb711f-ad70-5163-a31c-f05a6892a3bd', 1, 'noun', 'et', 'letter (of the alphabet)', 'Hvilket bogstav starter dit navn med?', 'What letter does your name start with?'), ('regulere', 'word', 'cac709d2-ef09-5ccf-9383-1c4fc142f990', 1, 'verb', null, 'to regulate, to adjust', 'Man skal regulere varmen i huset.', 'One should adjust the heat in the house.'), ('bagside', 'word', '50c00256-1bdd-56d0-9c80-1b6e1135b01b', 1, 'noun', 'en', 'back, reverse side', 'Der står noget på bagsiden af papiret.', 'There is something written on the back of the paper.'), ('styrte', 'word', '0b8320ad-91dc-5c9b-8630-b09dc3f42a5d', 1, 'verb', null, 'to crash', 'Flyet styrtede ned i havet.', 'The plane crashed into the sea.'), ('styrte', 'word', '0fd1736e-beb1-594e-a779-15c6f90c05b1', 2, 'verb', null, 'to rush, to dash', 'Han styrtede afsted for at nå bussen.', 'He dashed off to catch the bus.'), ('ansøger', 'word', '9feeba7f-5e05-5afc-bc4a-98ff43bd0a4f', 1, 'noun', 'en', 'applicant, candidate', 'Der er mange ansøgere til jobbet.', 'There are many applicants for the job.'), ('københavner', 'word', '9c6e6214-63fc-55c0-ab2f-86e52de689d7', 1, 'noun', 'en', 'Copenhagener', 'Han er født københavner.', 'He is a born Copenhagener.'), ('følsom', 'word', '6ac1e3d1-31a2-5338-b836-f9985492e86c', 1, 'adjective', null, 'sensitive', 'Hun er meget følsom over for kritik.', 'She is very sensitive to criticism.'), ('bekæmpelse', 'word', 'b16732db-0c5e-5e4b-bba7-9f01311d4565', 1, 'noun', 'en', 'combat, fight against', 'Bekæmpelse af fattigdom er vigtig.', 'The fight against poverty is important.'), ('absurd', 'word', '40b0791d-3c54-5436-b683-caf820a40afd', 1, 'adjective', null, 'absurd', 'Det er en helt absurd situation.', 'It is a completely absurd situation.'), ('appellere', 'word', 'd046c645-aa80-52da-841c-6fed0470ed5f', 1, 'verb', null, 'to appeal (a verdict)', 'Han vil appellere dommen.', 'He wants to appeal the verdict.'), ('appellere', 'word', '8025f26e-4f2f-53b4-a05f-4a08de0733de', 2, 'verb', null, 'to appeal to (reason, emotions)', 'Vi må appellere til folks fornuft.', 'We must appeal to people''s reason.'), ('uventet', 'word', 'cda3e4f3-a37d-5f72-96af-74f2ef249ab7', 1, 'adjective', null, 'unexpected', 'Det var et uventet besøg.', 'It was an unexpected visit.'), ('kemisk', 'word', '3d910de9-07eb-5065-abc9-e811ba94455b', 1, 'adjective', null, 'chemical', 'Det er en kemisk proces.', 'It is a chemical process.'), ('optimistisk', 'word', '646eaf69-9617-56eb-9db9-fa8ea2152ffd', 1, 'adjective', null, 'optimistic', 'Hun er meget optimistisk omkring fremtiden.', 'She is very optimistic about the future.'), ('benzin', 'word', 'ee1d07b3-decc-50e6-bd3f-d665fc660b12', 1, 'noun', 'en', 'gasoline, petrol', 'Jeg skal have fyldt benzin på bilen.', 'I need to fill the car with gasoline.'), ('barsk', 'word', '29b52b65-9166-54c8-a591-c5556425296c', 1, 'adjective', null, 'harsh, severe (weather)', 'Vejret er meget barsk i dag.', 'The weather is very harsh today.'), ('barsk', 'word', '0ebe25e0-a329-5630-a96d-38b6d929eb99', 2, 'adjective', null, 'blunt, gruff (manner)', 'Han fik en barsk besked.', 'He got a blunt message.'), ('sponsor', 'word', 'c275ef35-985e-57d8-9228-5c34ba58fe98', 1, 'noun', 'en', 'sponsor', 'Vi leder efter en ny sponsor til holdet.', 'We are looking for a new sponsor for the team.'), ('gårsdag', 'word', '456d189b-29e9-5255-bfce-b2df12dbd93f', 1, 'noun', 'en', 'yesterday (as a day)', 'Gårsdagen var meget travl.', 'Yesterday was very busy.'), ('aspekt', 'word', 'c20043ca-e5d1-51c6-ba9c-393d8bb51ac8', 1, 'noun', 'et', 'aspect', 'Vi skal se på sagen fra et andet aspekt.', 'We need to look at the case from another aspect.'), ('indspille', 'word', '7c7b8847-4f6a-5d81-a736-8eb82b03f266', 1, 'verb', null, 'to record (a song)', 'Bandet skal indspille en ny sang.', 'The band is going to record a new song.'), ('indspille', 'word', 'b10b5cce-0aa5-595b-9687-3a6095d590e0', 2, 'verb', null, 'to make, to star in (a film)', 'Hun har indspillet mange film.', 'She has starred in many films.'), ('australsk', 'word', '8b048c03-10dd-50b1-bc9f-9787322a53db', 1, 'adjective', null, 'Australian', 'Han er af australsk oprindelse.', 'He is of Australian origin.'), ('belgisk', 'word', 'aed4f44e-0c71-5e50-9a20-ab121b25f17f', 1, 'adjective', null, 'Belgian', 'Jeg elsker belgisk chokolade.', 'I love Belgian chocolate.'), ('præsidentvalg', 'word', '4231ed4f-e29d-519c-b3fd-5caa2eea7135', 1, 'noun', 'et', 'presidential election', 'Der er præsidentvalg næste år.', 'There is a presidential election next year.'), ('cigaret', 'word', 'e5c921a6-fbab-5cbe-9e13-8c21c78da024', 1, 'noun', 'en', 'cigarette', 'Han tændte en cigaret.', 'He lit a cigarette.'), ('karakteristisk', 'word', '52838d74-5c02-547c-bd69-08484c448f99', 1, 'adjective', null, 'characteristic, typical', 'Det er meget karakteristisk for ham.', 'It is very characteristic of him.'), ('fremlægge', 'word', '7cb4edb7-dee6-5704-86cd-895dd9f602d5', 1, 'verb', null, 'to present (a plan)', 'Han skal fremlægge sin plan.', 'He must present his plan.'), ('fremlægge', 'word', 'ad19dab9-a515-53ae-b0e0-53a713f76072', 2, 'verb', null, 'to submit, to produce (evidence)', 'Hun fremlagde beviserne i retten.', 'She produced the evidence in court.'), ('renovering', 'word', '9699a32e-f69c-5ade-9802-c12008e0196e', 1, 'noun', 'en', 'renovation', 'Huset trænger til en renovering.', 'The house needs a renovation.'), ('indsætte', 'word', 'edb0c02f-3592-5783-9158-12b3d508fd09', 1, 'verb', null, 'to deposit (money)', 'Jeg skal indsætte penge i banken.', 'I need to deposit money at the bank.'), ('indsætte', 'word', 'aa66bd7d-3aec-5456-862e-d001958862fb', 2, 'verb', null, 'to appoint (to a position)', 'De indsatte en ny direktør.', 'They appointed a new director.'), ('halvår', 'word', '67b7ab5d-80bd-5720-adb6-e8148f18c231', 1, 'noun', 'et', 'half-year, six-month period', 'Kurset varer et halvår.', 'The course lasts half a year.'), ('landevej', 'word', '0bfced65-affe-5728-8556-d795db9d5c61', 1, 'noun', 'en', 'country road, highway', 'Vi kørte ad en lille landevej.', 'We drove along a small country road.'), ('udfald', 'word', '9d2a8e66-616c-5112-9be9-6ffaaf986ba2', 1, 'noun', 'et', 'outcome, result', 'Vi kender ikke udfaldet endnu.', 'We do not know the outcome yet.'), ('udfald', 'word', 'ecdf8154-9b16-5ebd-819e-c8d418ec4ee6', 2, 'noun', 'et', 'attack, sally (verbal criticism)', 'Han kom med et skarpt udfald mod hende.', 'He made a sharp attack against her.'), ('neutral', 'word', '9d9e42e6-c26c-5179-ab4f-72f258b47a05', 1, 'adjective', null, 'neutral (politically)', 'Danmark var neutral under krigen.', 'Denmark was neutral during the war.'), ('neutral', 'word', 'b6a3e6bc-ded4-5639-84eb-cddd9a5d92d5', 2, 'adjective', null, 'neutral (bland, understated color)', 'Væggene har en neutral farve.', 'The walls have a neutral color.'), ('sær', 'word', '62631073-e7c6-5ffe-a590-3cf6051210cd', 1, 'adjective', null, 'strange, odd', 'Han har en sær måde at tale på.', 'He has a strange way of talking.'), ('kjole', 'word', '572234eb-b9b5-544a-9000-53536426add7', 1, 'noun', 'en', 'dress', 'Hun har en rød kjole på.', 'She is wearing a red dress.'), ('folketingsvalg', 'word', 'bbb41382-2078-5879-9d68-01a1b318d4cb', 1, 'noun', 'et', 'parliamentary election', 'Der er folketingsvalg i Danmark hvert fjerde år.', 'Parliamentary elections are held in Denmark every four years.'), ('snes', 'word', '7c5c651d-714c-5ea2-8723-1c80ed01f738', 1, 'noun', 'en', 'a score (twenty)', 'Der var et snes mennesker til stede.', 'About a score of people were present.'), ('mystisk', 'word', '9ffddcab-5dbc-5f31-8e1b-7ce28076fd69', 1, 'adjective', null, 'mysterious', 'Det var en mystisk lyd i nat.', 'There was a mysterious sound last night.'), ('mystisk', 'word', 'ebe5116e-07b4-56ff-b512-007fdac1e0ce', 2, 'adjective', null, 'odd, bizarre (behavior)', 'Han opfører sig meget mystisk.', 'He is behaving very oddly.'), ('markedsføring', 'word', '4f67f563-0202-52ee-896d-9c9e0a9781f6', 1, 'noun', 'en', 'marketing (the field)', 'Hun læser markedsføring på universitetet.', 'She studies marketing at university.'), ('markedsføring', 'word', '5c070122-eed5-5e0b-bdfa-af3008f84e38', 2, 'noun', 'en', 'marketing, promotion (of a product)', 'Virksomheden bruger mange penge på markedsføring.', 'The company spends a lot of money on marketing.'), ('ideologisk', 'word', '60b79c55-1055-50bf-b824-03c00122eb7e', 1, 'adjective', null, 'ideological', 'De har store ideologiske forskelle.', 'They have big ideological differences.'), ('kirkegård', 'word', '436d651a-261e-524b-959e-d0ace042d906', 1, 'noun', 'en', 'cemetery', 'De gik en tur på kirkegården.', 'They took a walk in the cemetery.'), ('bosætte', 'word', '0b0e9f9b-05c6-5fd0-ae7d-92a2ff1e0e76', 1, 'verb', null, 'to settle (in a place)', 'De valgte at bosætte sig i København.', 'They chose to settle in Copenhagen.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'locale-en-2026-09-25' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
